  insert into public.learning_skill_lessons(canonical_skill_id, version, title, summary, content_markdown, worked_example, tips, estimated_minutes, metadata, active) values (v_skill_id, 1, 'Como comparar materiais no dia a dia', 'Compare propriedades observáveis, relacione-as ao uso pretendido e confira se o objeto está seguro para reúso. Para descarte, siga a orientação local.', '## Objetivo
Observar propriedades de materiais e usá-las para explicar escolhas de uso e reúso.

## Antes de começar
- Reconhecer objetos usados em casa ou na escola
- Descrever diferenças que podem ser vistas ou sentidas com segurança

## Conceitos principais
- Material é aquilo de que um objeto é feito
- Propriedades são características que podemos observar
- Uma escolha responsável depende do uso e das condições do objeto

## Explicação passo a passo
1. Comece pelo objeto, não pelo nome do material: observe se é rígido ou flexível, transparente ou opaco, absorve água ou a deixa escorrer. Não toque em objetos quentes, cortantes ou desconhecidos.
2. Compare a propriedade com a tarefa. Um material que deixa a luz passar pode servir a uma janela; um material que absorve água pode ser útil para limpar um pequeno derramamento.
3. Para pensar em reúso, verifique se o objeto está limpo, inteiro e adequado ao novo uso. O destino de descarte depende das orientações da coleta local; não se deve adivinhar uma regra universal.

## Exemplo trabalhado
Imagine duas embalagens limpas: uma caixa de papelão e um pote plástico transparente. Para guardar folhas que precisam ficar visíveis, o pote permite enxergar o conteúdo; para proteger um desenho grande e plano, a caixa pode ser mais adequada. A decisão vem de comparar propriedades com a tarefa, não de dizer que um material é sempre melhor. Antes de reutilizar, um adulto verifica se a embalagem é segura e se está limpa.

## Erros comuns
- Achar que todos os objetos feitos do mesmo material têm exatamente as mesmas propriedades
- Escolher um destino de reciclagem sem consultar a orientação local
- Confundir uma aparência com prova de segurança para qualquer uso

## Como retomar
### COMPARE_ONE_PROPERTY
Retome uma propriedade por vez e pergunte o que foi observado no objeto.

Compare um papel seco e um plástico: qual deles absorve uma gota de água? A observação ajuda a escolher um material para secar uma mesa.

**Confira:** Consigo dizer qual propriedade observei e como ela combina com a tarefa?

### USE_AND_DESTINATION
Separe duas decisões: se o objeto está adequado para outro uso e qual regra local orienta o descarte.

Uma caixa limpa pode guardar brinquedos; se estiver molhada e muito danificada, talvez não sirva para isso. A coleta correta deve ser consultada com um adulto.

**Confira:** Avaliei o estado do objeto e consultei a orientação apropriada para o destino?

## Aplicação
Escolher entre uma sacola de pano e uma caixa para levar materiais escolares, explicando qual propriedade atende melhor ao uso.

## Resumo
Compare propriedades observáveis, relacione-as ao uso pretendido e confira se o objeto está seguro para reúso. Para descarte, siga a orientação local.

## Prática
Peça à criança que compare dois objetos seguros, registre uma propriedade de cada um e explique qual escolheria para uma tarefa concreta.', 'Imagine duas embalagens limpas: uma caixa de papelão e um pote plástico transparente. Para guardar folhas que precisam ficar visíveis, o pote permite enxergar o conteúdo; para proteger um desenho grande e plano, a caixa pode ser mais adequada. A decisão vem de comparar propriedades com a tarefa, não de dizer que um material é sempre melhor. Antes de reutilizar, um adulto verifica se a embalagem é segura e se está limpa.', ARRAY['Consigo dizer qual propriedade observei e como ela combina com a tarefa?', 'Avaliei o estado do objeto e consultei a orientação apropriada para o destino?']::text[], 10, '{"content_pack":"tec-escola-knowledge-expansion-v2","content_version":"2.0.0","mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","objective":"Observar propriedades de materiais e usá-las para explicar escolhas de uso e reúso.","prior_knowledge":["Reconhecer objetos usados em casa ou na escola","Descrever diferenças que podem ser vistas ou sentidas com segurança"],"key_concepts":["Material é aquilo de que um objeto é feito","Propriedades são características que podemos observar","Uma escolha responsável depende do uso e das condições do objeto"],"progressive_explanation":["Comece pelo objeto, não pelo nome do material: observe se é rígido ou flexível, transparente ou opaco, absorve água ou a deixa escorrer. Não toque em objetos quentes, cortantes ou desconhecidos.","Compare a propriedade com a tarefa. Um material que deixa a luz passar pode servir a uma janela; um material que absorve água pode ser útil para limpar um pequeno derramamento.","Para pensar em reúso, verifique se o objeto está limpo, inteiro e adequado ao novo uso. O destino de descarte depende das orientações da coleta local; não se deve adivinhar uma regra universal."],"common_errors":["Achar que todos os objetos feitos do mesmo material têm exatamente as mesmas propriedades","Escolher um destino de reciclagem sem consultar a orientação local","Confundir uma aparência com prova de segurança para qualquer uso"],"remediations":[{"id":"COMPARE_ONE_PROPERTY","trigger":"A criança escolhe sem indicar uma evidência","explanation":"Retome uma propriedade por vez e pergunte o que foi observado no objeto.","workedExample":"Compare um papel seco e um plástico: qual deles absorve uma gota de água? A observação ajuda a escolher um material para secar uma mesa.","selfCheck":"Consigo dizer qual propriedade observei e como ela combina com a tarefa?"},{"id":"USE_AND_DESTINATION","trigger":"A criança afirma que um material deve sempre ser descartado ou reaproveitado","explanation":"Separe duas decisões: se o objeto está adequado para outro uso e qual regra local orienta o descarte.","workedExample":"Uma caixa limpa pode guardar brinquedos; se estiver molhada e muito danificada, talvez não sirva para isso. A coleta correta deve ser consultada com um adulto.","selfCheck":"Avaliei o estado do objeto e consultei a orientação apropriada para o destino?"}],"everyday_application":"Escolher entre uma sacola de pano e uma caixa para levar materiais escolares, explicando qual propriedade atende melhor ao uso.","practice_guidance":"Peça à criança que compare dois objetos seguros, registre uma propriedade de cada um e explique qual escolheria para uma tarefa concreta."}'::jsonb, false) on conflict (canonical_skill_id, version) do update set title = excluded.title, summary = excluded.summary, content_markdown = excluded.content_markdown, worked_example = excluded.worked_example, tips = excluded.tips, estimated_minutes = excluded.estimated_minutes, metadata = excluded.metadata, active = false, updated_at = now() returning id into v_lesson_id;
