  insert into public.learning_skill_lessons(canonical_skill_id, version, title, summary, content_markdown, worked_example, tips, estimated_minutes, metadata, active) values (v_skill_id, 1, 'O que diferentes fontes contam sobre o lugar', 'Identifique quem produziu cada fonte, compare o que ela sustenta e registre acontecimentos sem inventar datas ou detalhes que não aparecem nos registros.', '## Objetivo
Usar fontes diferentes para registrar acontecimentos e reconhecer o limite de cada informação.

## Antes de começar
- Reconhecer que pessoas podem contar lembranças
- Ordenar acontecimentos simples como antes, depois e hoje

## Conceitos principais
- Fonte é um vestígio ou registro usado para investigar
- Fontes têm autores, datas e finalidades
- Uma afirmação deve combinar com o que a fonte realmente mostra

## Explicação passo a passo
1. Uma fotografia, uma notícia, um bilhete e uma conversa podem ser fontes diferentes. Observe quem fez o registro, quando e para qual finalidade, se essa informação estiver disponível.
2. Cada fonte sustenta algumas afirmações e deixa outras em aberto. Uma fotografia pode mostrar que uma praça tinha um brinquedo, mas sem data ou legenda ela não prova em que ano isso aconteceu.
3. Compare fontes sem decidir automaticamente que uma pessoa está mentindo quando há diferenças. Uma lembrança informa como alguém viveu ou recorda o acontecimento; um documento datado pode ajudar a situar quando algo foi registrado.

## Exemplo trabalhado
Uma moradora conta que a praça do bairro ganhou uma biblioteca quando ela era criança. Uma fotografia mostra a fachada da biblioteca, e um folheto da prefeitura traz o ano de inauguração. A lembrança ajuda a conhecer a experiência da moradora; a fotografia mostra a fachada; o folheto registra uma data. Juntas, as fontes permitem montar um registro mais cuidadoso. Se a fotografia não tiver data, não devemos afirmar que ela foi feita no ano do folheto.

## Erros comuns
- Achar que toda lembrança é falsa ou que toda lembrança prova sozinha todos os detalhes
- Atribuir data a uma fotografia sem legenda ou registro
- Tratar fontes diferentes como se tivessem a mesma finalidade

## Como retomar
### SOURCE_AUTHOR_DATE
Pergunte quem produziu o registro e se há data ou legenda antes de usá-lo.

Uma foto sem data mostra uma ponte, mas não informa quando foi construída. Procure uma legenda ou outro registro datado.

**Confira:** Consigo dizer quem fez a fonte e o que ela realmente mostra?

### MEMORY_AND_RECORD
Compare o tipo de informação que cada fonte oferece e registre as diferenças sem inventar uma solução.

Duas pessoas podem lembrar uma festa de modos diferentes. Um convite mostra a data planejada, enquanto cada relato descreve uma experiência.

**Confira:** Expliquei o que cada fonte apoia e o que continua sem confirmação?

## Aplicação
Montar com a família uma pequena linha do tempo de mudanças na escola usando uma fotografia identificada e um relato, anotando de onde veio cada informação.

## Resumo
Identifique quem produziu cada fonte, compare o que ela sustenta e registre acontecimentos sem inventar datas ou detalhes que não aparecem nos registros.

## Prática
Use fontes fictícias ou autorizadas, peça que a criança cite a evidência para cada afirmação e aceite respostas que reconheçam limites ou incertezas.', 'Uma moradora conta que a praça do bairro ganhou uma biblioteca quando ela era criança. Uma fotografia mostra a fachada da biblioteca, e um folheto da prefeitura traz o ano de inauguração. A lembrança ajuda a conhecer a experiência da moradora; a fotografia mostra a fachada; o folheto registra uma data. Juntas, as fontes permitem montar um registro mais cuidadoso. Se a fotografia não tiver data, não devemos afirmar que ela foi feita no ano do folheto.', ARRAY['Consigo dizer quem fez a fonte e o que ela realmente mostra?', 'Expliquei o que cada fonte apoia e o que continua sem confirmação?']::text[], 10, '{"content_pack":"tec-escola-knowledge-expansion-v2","content_version":"2.0.0","mapping_status":"MAPPING_PENDING","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","objective":"Usar fontes diferentes para registrar acontecimentos e reconhecer o limite de cada informação.","prior_knowledge":["Reconhecer que pessoas podem contar lembranças","Ordenar acontecimentos simples como antes, depois e hoje"],"key_concepts":["Fonte é um vestígio ou registro usado para investigar","Fontes têm autores, datas e finalidades","Uma afirmação deve combinar com o que a fonte realmente mostra"],"progressive_explanation":["Uma fotografia, uma notícia, um bilhete e uma conversa podem ser fontes diferentes. Observe quem fez o registro, quando e para qual finalidade, se essa informação estiver disponível.","Cada fonte sustenta algumas afirmações e deixa outras em aberto. Uma fotografia pode mostrar que uma praça tinha um brinquedo, mas sem data ou legenda ela não prova em que ano isso aconteceu.","Compare fontes sem decidir automaticamente que uma pessoa está mentindo quando há diferenças. Uma lembrança informa como alguém viveu ou recorda o acontecimento; um documento datado pode ajudar a situar quando algo foi registrado."],"common_errors":["Achar que toda lembrança é falsa ou que toda lembrança prova sozinha todos os detalhes","Atribuir data a uma fotografia sem legenda ou registro","Tratar fontes diferentes como se tivessem a mesma finalidade"],"remediations":[{"id":"SOURCE_AUTHOR_DATE","trigger":"A criança usa uma fonte sem dizer de onde veio","explanation":"Pergunte quem produziu o registro e se há data ou legenda antes de usá-lo.","workedExample":"Uma foto sem data mostra uma ponte, mas não informa quando foi construída. Procure uma legenda ou outro registro datado.","selfCheck":"Consigo dizer quem fez a fonte e o que ela realmente mostra?"},{"id":"MEMORY_AND_RECORD","trigger":"A criança escolhe entre fontes diferentes como se uma anulasse automaticamente a outra","explanation":"Compare o tipo de informação que cada fonte oferece e registre as diferenças sem inventar uma solução.","workedExample":"Duas pessoas podem lembrar uma festa de modos diferentes. Um convite mostra a data planejada, enquanto cada relato descreve uma experiência.","selfCheck":"Expliquei o que cada fonte apoia e o que continua sem confirmação?"}],"everyday_application":"Montar com a família uma pequena linha do tempo de mudanças na escola usando uma fotografia identificada e um relato, anotando de onde veio cada informação.","practice_guidance":"Use fontes fictícias ou autorizadas, peça que a criança cite a evidência para cada afirmação e aceite respostas que reconheçam limites ou incertezas."}'::jsonb, false) on conflict (canonical_skill_id, version) do update set title = excluded.title, summary = excluded.summary, content_markdown = excluded.content_markdown, worked_example = excluded.worked_example, tips = excluded.tips, estimated_minutes = excluded.estimated_minutes, metadata = excluded.metadata, active = false, updated_at = now() returning id into v_lesson_id;
